"""abacus: tpch/Q27; common numeric v4; explicitly rewritten workload.
Source: original/tpch/plop/Q27.sql
Run via experiments.validation.faithful_runtime; model settings are external.
"""
SYSTEM = 'abacus'
QUERY_ID = 'tpch/Q27'
SOURCE = 'original/tpch/plop/Q27.sql'

RELATIONAL_SQL = "WITH joined AS (\n  SELECT\n    pf.p_partkey,\n    pf.p_name,\n    pf.p_type,\n    pf.p_brand,\n    sb.ps_suppkey,\n    sb.s_name,\n    sb.s_acctbal,\n    sb.s_comment,\n    sb.nation_name,\n    sb.region_name,\n    sb.ps_availqty,\n    sb.ps_supplycost,\n    ol.l_orderkey,\n    ol.l_quantity,\n    ol.l_extendedprice,\n    ol.o_orderdate,\n    ol.o_orderpriority,\n    ol.o_totalprice\n  FROM (\n    SELECT\n      p.p_partkey,\n      p.p_name,\n      p.p_type,\n      p.p_brand,\n      p.p_size\n    FROM part AS p\n    WHERE\n      SEMANTIC_FILTER(\n        'You are screening parts for strategic sourcing analysis. Looking at part name, type, brand, and size, does this look like a differentiated component where supplier quality and pricing strategy would matter?\nPart Name: {0}\nPart Type: {1}\nBrand: {2}\nSize: {3}\nReturn a single YES or NO, with no other words. If uncertain, return YES.',\n        CAST(p.p_name AS TEXT),\n        CAST(p.p_type AS TEXT),\n        CAST(p.p_brand AS TEXT),\n        CAST(p.p_size AS TEXT)\n      )\n  ) AS pf\n  JOIN (\n    SELECT\n      ps.ps_partkey,\n      ps.ps_suppkey,\n      ps.ps_availqty,\n      ps.ps_supplycost,\n      s.s_name,\n      s.s_acctbal,\n      s.s_comment,\n      s.s_nationkey,\n      n.n_name AS nation_name,\n      r.r_name AS region_name\n    FROM partsupp AS ps\n    JOIN supplier AS s\n      ON s.s_suppkey = ps.ps_suppkey\n    JOIN nation AS n\n      ON n.n_nationkey = s.s_nationkey\n    JOIN region AS r\n      ON r.r_regionkey = n.n_regionkey\n    WHERE\n      ps.ps_availqty BETWEEN 10 AND 600\n      AND ps.ps_supplycost BETWEEN 20 AND 900\n      AND r.r_name IN ('EUROPE', 'ASIA', 'AMERICA')\n  ) AS sb\n    ON sb.ps_partkey = pf.p_partkey\n  JOIN (\n    SELECT\n      l.l_partkey,\n      l.l_suppkey,\n      l.l_orderkey,\n      l.l_quantity,\n      l.l_extendedprice,\n      l.l_discount,\n      o.o_orderdate,\n      o.o_orderpriority,\n      o.o_totalprice\n    FROM lineitem AS l\n    JOIN orders AS o\n      ON o.o_orderkey = l.l_orderkey\n    WHERE\n      o.o_orderdate >= CAST('1994-01-01' AS DATE)\n      AND o.o_orderdate < CAST('1997-01-01' AS DATE)\n      AND l.l_quantity BETWEEN 8 AND 35\n      AND l.l_discount BETWEEN 0.00 AND 0.08\n  ) AS ol\n    ON ol.l_partkey = sb.ps_partkey AND ol.l_suppkey = sb.ps_suppkey\n)\nSELECT\n  *\nFROM joined AS j\nJOIN (\n  SELECT\n    s.s_suppkey,\n    s.s_name,\n    s.s_address,\n    s.s_nationkey,\n    s.s_phone,\n    s.s_acctbal,\n    s.s_comment\n  FROM supplier AS s\n  JOIN (\n    SELECT DISTINCT\n      ps_suppkey\n    FROM joined\n    ORDER BY\n      ps_suppkey ASC\n    LIMIT 80\n  ) AS k\n    ON k.ps_suppkey = s.s_suppkey\n  WHERE\n    SEMANTIC_FILTER(\n      'You are shortlisting suppliers for long-term procurement partnerships. Based on supplier identity style, account balance, and profile comment tone, does this supplier appear commercially dependable enough for preferred-vendor consideration?\nSupplier Name: {0}\nAccount Balance: {1}\nComment: {2}\nReturn a single YES or NO, with no other words. If uncertain, return YES.',\n      CAST(s.s_name AS TEXT),\n      CAST(s.s_acctbal AS TEXT),\n      CAST(s.s_comment AS TEXT)\n    )\n) AS sc\n  ON sc.s_suppkey = j.ps_suppkey\n  AND SEMANTIC_JOIN(\n    'You are validating whether this supplier profile is suitable for preferred-vendor sourcing.\nPart Type: {0}\nRegion: {1}\nSupplier Name: {2}\nAccount Balance: {3}\nComment: {4}\nReturn a single YES or NO, with no other words. If uncertain, return YES.',\n    CAST(j.p_type AS TEXT),\n    CAST(j.region_name AS TEXT),\n    CAST(sc.s_name AS TEXT),\n    CAST(sc.s_acctbal AS TEXT),\n    CAST(sc.s_comment AS TEXT)\n  );\n"

def run(tables, job, semantic=None):
    from experiments.validation.faithful_runtime import run_relational
    return run_relational(SYSTEM, RELATIONAL_SQL, tables, job, semantic=semantic)

if __name__ == '__main__':
    from experiments.validation.faithful_runtime import query_main
    query_main(globals())
